// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, address _target, uint256 _initialBalance) public {
        vm.assume(_value <= type(uint128).max);
        vm.assume(_initialBalance >= _value);
        vm.assume(_initialBalance <= type(uint128).max);
        Reverter reverter = new Reverter();
        vm.deal(address(c), _initialBalance);
        uint256 prevBalance = address(c).balance;
        vm.prank(c.owner());
        bool ok = true;
        try c.sendMoney(address(reverter), _value) { ok = true; } catch { ok = false; }
        uint256 newBalance = address(c).balance;
        assertTrue(ok ? newBalance == prevBalance - _value : newBalance == prevBalance);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
